PROCEDURE CREARLISTA(VAR L: T_LISTA);
BEGIN
  L.CAB := NIL;  // Inicializamos la lista como vacía
  L.TAM := 0;
END;

PROCEDURE AGREGAR(VAR L: T_LISTA; X: T_DATO);
VAR
  NUEVO, ACTUAL, ANTERIOR: T_PUNTERO;
BEGIN
  NEW(NUEVO);         // Reservamos memoria para el nuevo nodo
  NUEVO^.INFO := X;   // Guardamos los datos
  NUEVO^.SIG := NIL;  // El siguiente nodo será NIL

  // Si la lista está vacía o el nuevo nodo es menor, lo insertamos al inicio
  IF (L.CAB = NIL) OR (X.NOM < L.CAB^.INFO.NOM) THEN
  BEGIN
    NUEVO^.SIG := L.CAB;
    L.CAB := NUEVO;
  END
  ELSE
  BEGIN
    // Buscamos la posición correcta para insertar el nodo
    ANTERIOR := NIL;
    ACTUAL := L.CAB;

    WHILE (ACTUAL <> NIL) AND (X.NOM >= ACTUAL^.INFO.NOM) DO
    BEGIN
      ANTERIOR := ACTUAL;
      ACTUAL := ACTUAL^.SIG;
    END;

    NUEVO^.SIG := ACTUAL;
    ANTERIOR^.SIG := NUEVO;
  END;

  INC(L.TAM); // Incrementamos el tamaño de la lista
END;

PROCEDURE ELIMINAR(VAR L: T_LISTA; BUSCADO: STRING; VAR X: T_DATO);
VAR
  ACTUAL, ANTERIOR: T_PUNTERO;
BEGIN
  IF L.CAB = NIL THEN EXIT; // Si la lista está vacía, no hacemos nada

  // Si el nodo a eliminar está al inicio
  IF L.CAB^.INFO.NOM = BUSCADO THEN
  BEGIN
    X := L.CAB^.INFO;
    ACTUAL := L.CAB;
    L.CAB := L.CAB^.SIG;
    DISPOSE(ACTUAL);
  END
  ELSE
  BEGIN
    // Buscamos el nodo a eliminar
    ANTERIOR := NIL;
    ACTUAL := L.CAB;

    WHILE (ACTUAL <> NIL) AND (ACTUAL^.INFO.NOM <> BUSCADO) DO
    BEGIN
      ANTERIOR := ACTUAL;
      ACTUAL := ACTUAL^.SIG;
    END;

    // Si lo encontramos, lo eliminamos
    IF ACTUAL <> NIL THEN
    BEGIN
      X := ACTUAL^.INFO;
      ANTERIOR^.SIG := ACTUAL^.SIG;
      DISPOSE(ACTUAL);
    END;
  END;

  DEC(L.TAM); // Reducimos el tamaño de la lista
END;

FUNCTION LISTA_VACIA(VAR L: T_LISTA): BOOLEAN;
BEGIN
  LISTA_VACIA := (L.CAB = NIL);
END;

FUNCTION LISTA_LLENA(VAR L: T_LISTA): BOOLEAN;
BEGIN
  LISTA_LLENA := (GETHEAPSTATUS.TotalFree < SIZEOF(T_NODO));
END;

PROCEDURE PRIMERO(VAR L: T_LISTA);
BEGIN
  L.CAB := L.CAB; // El primer nodo ya está en CAB
END;

FUNCTION FIN(L: T_LISTA): BOOLEAN;
BEGIN
  FIN := (L.CAB = NIL); // Fin si CAB apunta a NIL
END;

PROCEDURE SIGUIENTE(VAR L: T_LISTA);
BEGIN
  IF L.CAB <> NIL THEN
    L.CAB := L.CAB^.SIG; // Avanzamos al siguiente nodo
END;

PROCEDURE RECUPERAR(L: T_LISTA; VAR X: T_DATO);
BEGIN
  IF L.CAB <> NIL THEN
    X := L.CAB^.INFO; // Devolvemos el contenido del nodo actual
END;

END.

