UNIT colas;
INTERFACE
TYPE  T_DATO = RECORD   
 NOM: STRING[40];    
 TEL: STRING[15]; 
  END;
  T_PUNT = ^T_NODO;
  T_NODO = RECORD    
  INFO: T_DATO;    
  SIG: T_PUNT;
   END;
  T_COLA = RECORD  
    FRENTE, FINAL: T_PUNT;    
    TAM: WORD; 
     END;
PROCEDURE CREARCOLA(VAR Q: T_COLA);
BEGIN
  Q.TAM := 0;
  Q.FRENTE := NIL;
  Q.FINAL := NIL;
END;
PROCEDURE ENCOLAR(VAR Q: T_COLA; X: T_DATO);
VAR
  DIR: T_PUNT;
BEGIN
  NEW(DIR);
  DIR^.INFO := X;
  DIR^.SIG := NIL;

  IF Q.FRENTE = NIL THEN
    Q.FRENTE := DIR
  ELSE
    Q.FINAL^.SIG := DIR;

  Q.FINAL := DIR;
  INC(Q.TAM);
END;

FUNCTION COLA_LLENA(VAR Q: T_COLA): BOOLEAN;
BEGIN
  COLA_LLENA := GETHEAPSTATUS.TotalFree < SIZEOF(T_NODO);
END;

FUNCTION COLA_VACIA(VAR Q: T_COLA): BOOLEAN;
BEGIN
  COLA_VACIA := Q.TAM = 0;
END;

PROCEDURE DESENCOLAR(VAR Q: T_COLA; VAR X: T_DATO);
VAR
  ACT: T_PUNT;
BEGIN
  X := Q.FRENTE^.INFO;
  ACT := Q.FRENTE;
  Q.FRENTE := ACT^.SIG;
  DISPOSE(ACT);

  IF Q.FRENTE = NIL THEN
    Q.FINAL := NIL;

  DEC(Q.TAM);
END;

END.

